    public class GarnetAadAuthenticatorTests
    {
        private readonly Mock<ILogger> _mockLogger;
        private readonly Mock<IssuerSigningTokenProvider> _mockSigningTokenProvider;
        private readonly List<string> _authorizedAppIds;
        private readonly List<string> _audiences;
        private readonly List<string> _issuers;
        private readonly bool _validateUsername;

        public GarnetAadAuthenticatorTests()
        {
            _mockLogger = new Mock<ILogger>();
            _mockSigningTokenProvider = new Mock<IssuerSigningTokenProvider>();
            _authorizedAppIds = new List<string> { "app1", "app2" };
            _audiences = new List<string> { "audience1", "audience2" };
            _issuers = new List<string> { "issuer1", "issuer2" };
            _validateUsername = true;
        }

        [Fact]
        public void Authenticate_ValidCredentials_ReturnsTrue()
        {
            // Arrange
            var authenticator = new GarnetAadAuthenticator(
                _authorizedAppIds,
                _audiences,
                _issuers,
                _mockSigningTokenProvider.Object,
                _validateUsername,
                _mockLogger.Object);

            var password = Encoding.UTF8.GetBytes("validPassword");
            var username = Encoding.UTF8.GetBytes("validUsername");

            var tokenHandler = new JwtSecurityTokenHandler();
            var tokenDescriptor = new SecurityTokenDescriptor
            {
                Subject = new ClaimsIdentity(new Claim[]
                {
                    new Claim("appid", "app1"),
                    new Claim("http://schemas.microsoft.com/identity/claims/objectidentifier", "validUsername")
                }),
                Expires = DateTime.UtcNow.AddHours(1),
                Issuer = "issuer1",
                Audience = "audience1",
                SigningCredentials = new SigningCredentials(new SymmetricSecurityKey(Encoding.UTF8.GetBytes("secret")), SecurityAlgorithms.HmacSha256Signature)
            };
            var token = tokenHandler.CreateToken(tokenDescriptor);
            var tokenString = tokenHandler.WriteToken(token);

            _mockSigningTokenProvider.Setup(x => x.SigningTokens).Returns(new List<SecurityKey> { new SymmetricSecurityKey(Encoding.UTF8.GetBytes("secret")) });

            // Act
            var result = authenticator.Authenticate(password, username);

            // Assert
            Assert.True(result);
            _mockLogger.Verify(logger => logger.Log(
                It.Is<LogLevel>(logLevel => logLevel == LogLevel.Information),
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => true),
                It.IsAny<Exception>(),
                It.Is<Func<It.IsAnyType, Exception, string>>((v, t) => true)), Times.Once);
        }

        [Fact]
        public void Authenticate_InvalidCredentials_ReturnsFalse()
        {
            // Arrange
            var authenticator = new GarnetAadAuthenticator(
                _authorizedAppIds,
                _audiences,
                _issuers,
                _mockSigningTokenProvider.Object,
                _validateUsername,
                _mockLogger.Object);

            var password = Encoding.UTF8.GetBytes("invalidPassword");
            var username = Encoding.UTF8.GetBytes("invalidUsername");

            // Act
            var result = authenticator.Authenticate(password, username);

            // Assert
            Assert.False(result);
            _mockLogger.Verify(logger => logger.Log(
                It.Is<LogLevel>(logLevel => logLevel == LogLevel.Error),
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => true),
                It.IsAny<Exception>(),
                It.Is<Func<It.IsAnyType, Exception, string>>((v, t) => true)), Times.Once);
        }
    }
}
